import { TrainerWithUser } from "../../Interfaces/Trainer/TrainerWithUserInterface";
import { getTrainerSpecializationsByTrainerId } from "../../Services/TrainerSpecializationService";
import { useEffect, useState } from "react";
import "./TrainerCard.css";
import { Specialization } from "../../Interfaces/Specialization/SpecializationInterface";
import { getLocationByIdLikeString } from "../../Services/LocationService";
import Card from "../CardContainer/Card";

const TrainerCard = ({ trainer, user }: TrainerWithUser) => {
  const [specializations, setSpecializations] = useState<Specialization[]>([]);
  const [location, setLocation] = useState<string>("Location not available");

  console.log(trainer);
  useEffect(() => {
    const fetchSpecializations = async () => {
      try {
        console.log(trainer.id);
        const specializationsList = await getTrainerSpecializationsByTrainerId(
          trainer.id
        );
        if (specializationsList) {
          setSpecializations(specializationsList);
          console.log(specializations);
        } else {
          console.warn(
            `No specializations found for trainer with ID ${trainer.id}`
          );
        }
      } catch (error) {
        console.error("Failed to fetch specializations:", error);
      }
    };
    const fetchLocation = async () => {
      try {
        const location = await getLocationByIdLikeString(trainer.locationId!);
        setLocation(location || "Location not available");
      } catch (error) {
        console.error("Failed to fetch location:", error);
        return "Location not available";
      }
    };

    fetchLocation();
    fetchSpecializations();
  }, []);

  return (
    <Card className="trainer-card">
      <div className="trainer-card-header">
        <h2>
          {user.firstName} {user.lastName}
        </h2>
      </div>
      <div className="trainer-card-body">
        {specializations.length > 0 ? (
          <p className="specializations-line">
            {specializations.map((spec) => spec.name).join(", ")}
          </p>
        ) : (
          <p>No specializations available for this trainer...</p>
        )}
        <p>
          <strong>Raing:</strong> {trainer.avgRating}
        </p>
        <p>
          <strong>Bio:</strong> {trainer.bio}
        </p>
        <p>
          <strong>Location:</strong> {location}
        </p>
      </div>
      <div className="trainer-controls">
        <button>Sign up for classes</button>
      </div>
    </Card>
  );
};

export default TrainerCard;
